#!/usr/bin/env python3"""招投标每日聚合推送 — 四平台数据汇总，按采购意向/招标/中标+台州公安专项分类输出数据源: zjgov (浙江政采) + tzgg (台州工程) + lecaiyun (乐采云) + tzygcg (台州阳光采购)输出: 3~4段报告，用 ===MSG_SEPARATOR=== 分隔  第1-3段: 采购意向/招标/中标  第4段(有数据时): 台州公安系统采购专项用法:  python3 daily_aggregate.py              # 默认昨天  python3 daily_aggregate.py 2026-06-03   # 指定日期"""import jsonimport osimport sysimport refrom datetime import datetime, timedeltafrom pathlib import Pathfrom typing import Optional, Dict, List, Tuplefrom difflib import SequenceMatcherSCRIPT_DIR = Path(__file__).parentLOG_DIR = SCRIPT_DIR / "logs"LOG_DIR.mkdir(exist_ok=True)KEYWORDS_FILE = SCRIPT_DIR / "keywords_config.json"# ── 台州公安系统过滤 ────────────────────────────────────# 台州区县位置关键词（用于匹配采购单位是否属于台州公安系统）TAIZHOU_LOCATIONS = [    "台州", "椒江", "黄岩", "路桥",    "温岭", "临海", "玉环", "天台", "仙居", "三门",]# 公安系统单位关键词POLICE_UNIT_KEYWORDS = [    "公安", "交通警察", "交警",]def is_taizhou_police(unit_name: str) -> bool:    """    判断采购单位是否属于台州公安系统    匹配逻辑: 单位名称含公安相关关键词 且 含台州区县位置    覆盖: 台州市公安局、各区分局、各县市公安局及其下属单位    """    if not unit_name:        return False    has_police = any(kw in unit_name for kw in POLICE_UNIT_KEYWORDS)    has_location = any(loc in unit_name for loc in TAIZHOU_LOCATIONS)    return has_police and has_location# ── 工具 ──────────────────────────────────────────────────def find_latest_data_file(prefix: str, date_str: str) -> Optional[Path]:    for f in sorted(SCRIPT_DIR.glob(f"{prefix}*.json"), reverse=True):        m = re.search(r'(\d{4}-\d{2}-\d{2})', f.name)        if m and m.group(1) <= date_str:            return f    return Nonedef load_keywords() -> List[str]:    if KEYWORDS_FILE.exists():        try:            return json.loads(KEYWORDS_FILE.read_text(encoding="utf-8")).get("keywords", [])        except:            pass    return []def match_keywords(text: str, keywords: List[str]) -> bool:    if not text or not keywords:        return False    return any(kw in text for kw in keywords)def fmt_amount(val) -> str:    if not val:        return ""    try:        v = float(str(val).replace(",", "").replace("，", "").strip())        if v <= 0:            return ""        if v >= 10000:            w = v / 10000            if w >= 10000:                return f"¥{w/10000:.2f}亿"            return f"¥{w:.1f}万"        return f"¥{v:,.0f}"    except:        return ""def is_garbage_winner(name: str) -> bool:    """过滤明显不是中标单位名称的垃圾数据"""    if not name:        return True    name = name.strip()    if len(name) > 60:        return True    garbage_patterns = [        "按招标文件", "代理服务费", "服务费", "收费标准", "差额定率",        "向中标单位收取", "一次性付清", "不得超过",        "开户行", "账号", "联系电话", "参照以下",        "中标人须在", "费率计算", "户名", "/",        "方式计算", "计算方式", "如下",    ]    return any(p in name for p in garbage_patterns)def clean_title(title: str) -> str:    if not title:        return ""    title = title.strip()    if len(title) > 70:        title = title[:67] + "..."    return titledef normalize_title(title: str) -> str:    """标准化标题用于去重比较：去掉常见干扰词、标点、空白"""    if not title:        return ""    t = title.strip()    # 去掉常见修饰词（这些不影响项目本质）    noise_words = [        "中标候选人公示", "中标结果公告", "中标结果", "中标公告",        "招标公告", "采购公告", "采购意向公开",        "（重新招标）", "（二次招标）", "（三次招标）",        "(重新招标)", "(二次招标)", "(三次招标)",        "（", "）", "(", ")", "【", "】", "[", "]",        "竞争性磋商", "竞争性谈判", "公开招标", "询价采购",        "的", "之",    ]    for w in sorted(noise_words, key=len, reverse=True):        t = t.replace(w, "")    # 去掉多余空白    t = re.sub(r'\s+', '', t)    return t.lower()def title_similarity(a: str, b: str) -> float:    """计算两个标题的相似度（标准化后）"""    na = normalize_title(a)    nb = normalize_title(b)    if not na or not nb:        return 0.0    return SequenceMatcher(None, na, nb).ratio()def deduplicate_entries(entries: List[dict]) -> List[dict]:    """    跨数据源去重：合并相似标题的条目    - 相似度 > 0.65 视为重复    - 保留信息更丰富的条目（优先有中标单位/金额的）    - 优先保留 台州工程 > 浙江政采 > 乐采云（信息来源可靠度排序）    """    if len(entries) <= 1:        return entries    merged = []    used = set()    source_rank = {"台州工程": 1, "浙江政采": 2, "乐采云": 3}    for i, entry in enumerate(entries):        if i in used:            continue        best = dict(entry)  # copy        best_score = _entry_score(entry)        merged_indices = [i]        for j in range(i + 1, len(entries)):            if j in used:                continue            sim = title_similarity(entry["title"], entries[j]["title"])            if sim > 0.65:                used.add(j)                merged_indices.append(j)                score_j = _entry_score(entries[j])                # 如果 j 的信息更丰富且来源更可靠，替换 best                if score_j > best_score or (                    score_j == best_score                    and source_rank.get(entries[j].get("source", ""), 99)                    < source_rank.get(best.get("source", ""), 99)                ):                    best = dict(entries[j])                    best_score = score_j                    # 保留原条目的 URL（如果 best 没有更好的 URL）                    if not best.get("url") and entry.get("url"):                        best["url"] = entry["url"]        merged.append(best)    if len(merged) < len(entries):        removed = len(entries) - len(merged)        print(f"[DEDUP] {len(entries)}条 → {len(merged)}条 (去重 {removed} 条)", file=sys.stderr)    return mergeddef _entry_score(entry: dict) -> int:    """计算条目信息完整度分数，用于去重时选择保留哪个"""    score = 0    if entry.get("winning_unit"):        score += 3    if entry.get("winning_amount"):        score += 3    if entry.get("budget"):        score += 2    if entry.get("unit"):        score += 1    if entry.get("url"):        score += 1    # 中标结果公告比中标候选人公示信息更完整    title = entry.get("title", "")    if "中标结果公告" in title:        score += 2    elif "中标结果" in title:        score += 1    return score# ── 数据加载 ──────────────────────────────────────────────def load_zjgov(data_file: Optional[Path]) -> Dict[str, list]:    result: Dict[str, list] = {"意向": [], "意见征询": [], "招标": [], "中标": []}    if not data_file or not data_file.exists():        return result    try:        data = json.loads(data_file.read_text(encoding="utf-8"))    except Exception as e:        print(f"[WARN] zjgov: {e}", file=sys.stderr)        return result    items = data.get("items", [])    details = data.get("details", {})    cat_map = {"采购意向公开": "意向", "意见征询": "意见征询", "采购项目公告": "招标", "采购结果公告": "中标"}    for item in items:        target = cat_map.get(item.get("category", ""))        if not target:            continue        aid = item.get("article_id", "")        d = details.get(aid, {})        title = d.get("project_name") or item.get("title", "")        url = item.get("detail_url", "")        unit = d.get("采购人名称") or item.get("author", "")        budget = fmt_amount(d.get("预算金额") or item.get("list_budget", ""))        entry = {"source": "浙江政采", "title": clean_title(title), "url": url, "unit": unit, "budget": budget}        if target == "中标":            wu = d.get("中标供应商", "")            if is_garbage_winner(wu):                wu = ""            wa = fmt_amount(d.get("中标金额", ""))            entry["winning_unit"] = wu            entry["winning_amount"] = wa        result[target].append(entry)    return resultdef load_tzgg(data_file: Optional[Path]) -> Dict[str, list]:    result: Dict[str, list] = {"意向": [], "意见征询": [], "招标": [], "中标": []}    if not data_file or not data_file.exists():        return result    try:        data = json.loads(data_file.read_text(encoding="utf-8"))    except Exception as e:        print(f"[WARN] tzgg: {e}", file=sys.stderr)        return result    items = data.get("items", [])    dets = data.get("details", {})    for item in items:        iid = item.get("infoid", "")        d = dets.get(iid, {})        cat = item.get("categoryname", "")        title = item.get("title", "")        url = item.get("infourl", "")        if url and not url.startswith("http"):            url = "https://ggzy.tzztb.zjtz.gov.cn" + url        if cat == "招标公告":            unit = d.get("招标人", "") or item.get("xiaquname", "")            b = d.get("预算金额(万元)", "")            budget = f"¥{b}万" if b else ""            entry = {"source": "台州工程", "title": clean_title(title), "url": url, "unit": unit, "budget": budget}            result["招标"].append(entry)        elif cat in ("中标候选人公示", "中标结果公告"):            unit = d.get("招标人", "") or item.get("xiaquname", "")            b = d.get("预算金额(万元)", "")            budget = f"¥{b}万" if b else ""            wu = d.get("中标单位名称", "")            wa_raw = d.get("中标金额(万元)", "")            wa = f"¥{wa_raw}万" if wa_raw else ""            entry = {"source": "台州工程", "title": clean_title(title), "url": url, "unit": unit, "budget": budget, "winning_unit": wu, "winning_amount": wa}            result["中标"].append(entry)    return resultdef load_lecaiyun(data_file: Optional[Path], keywords: List[str]) -> Dict[str, list]:    result: Dict[str, list] = {"意向": [], "意见征询": [], "招标": [], "中标": []}    if not data_file or not data_file.exists():        return result    try:        data = json.loads(data_file.read_text(encoding="utf-8"))    except Exception as e:        print(f"[WARN] lecaiyun: {e}", file=sys.stderr)        return result    items_by_cat = data.get("items", {})    cat_map = {"采购意向公开": "意向", "意见征询": "意见征询", "需求公示": "意见征询", "招标公告": "招标", "中标公告": "中标"}    noise_kw = ["采购单位指南", "供应商指南", "帮助中心"]    for cat_name, target in cat_map.items():        for item in items_by_cat.get(cat_name, []):            title = item.get("title", "")            if not title or any(k in title for k in noise_kw):                continue            if not match_keywords(title, keywords):                continue            url = item.get("url", "")            budget = fmt_amount(item.get("budget", ""))            unit = item.get("unit", "")            entry = {"source": "乐采云", "title": clean_title(title), "url": url, "unit": unit, "budget": budget}            if target == "中标":                wu = item.get("winning_unit", "")                wa = fmt_amount(item.get("winning_amount", ""))                entry["winning_unit"] = wu if not is_garbage_winner(wu) else ""                entry["winning_amount"] = wa            result[target].append(entry)    return resultdef load_tzygcg(data_file: Optional[Path]) -> Dict[str, list]:    """加载台州阳光采购平台数据"""    result: Dict[str, list] = {"意向": [], "意见征询": [], "招标": [], "中标": []}    if not data_file or not data_file.exists():        return result    try:        data = json.loads(data_file.read_text(encoding="utf-8"))    except Exception as e:        print(f"[WARN] tzygcg: {e}", file=sys.stderr)        return result    items = data.get("items", [])    for item in items:        title = item.get("title", "")        url = item.get("source_url", "")        unit = item.get("buyer", "")        budget = fmt_amount(item.get("budget", ""))        category = item.get("category", "")        entry = {"source": "台州阳光采购", "title": clean_title(title), "url": url, "unit": unit, "budget": budget}        if category == "中标":            wu = item.get("winner", "")            if is_garbage_winner(wu):                wu = ""            wa = fmt_amount(item.get("winAmount", ""))            entry["winning_unit"] = wu            entry["winning_amount"] = wa            result["中标"].append(entry)        elif category == "招标":            result["招标"].append(entry)        elif category == "意见征询":            result["意见征询"].append(entry)    return resultdef cross_category_dedup(    intent: List[dict], yjzq: List[dict], bidding: List[dict], winning: List[dict]) -> Tuple[List[dict], List[dict], List[dict], List[dict]]:    """    跨分类URL去重：同一URL出现在多个分类时，只保留最高阶段。    优先级: 中标 > 招标 > 意见征询 > 意向    同时也会检查标题高度相似的条目（不同平台可能URL不同但标题相同）    """    # Phase 1: URL-based dedup    winning_urls = {e["url"] for e in winning if e.get("url")}    bidding_urls = {e["url"] for e in bidding if e.get("url")}    yjzq_urls = {e["url"] for e in yjzq if e.get("url")}    # Filter intent: remove if URL already in higher stages    filtered_intent = []    removed_from_intent = 0    for e in intent:        url = e.get("url", "")        if url and (url in winning_urls or url in bidding_urls or url in yjzq_urls):            removed_from_intent += 1            continue        filtered_intent.append(e)    # Filter 意见征询: remove if URL in 招标 or 中标    filtered_yjzq = []    removed_from_yjzq = 0    for e in yjzq:        url = e.get("url", "")        if url and (url in winning_urls or url in bidding_urls):            removed_from_yjzq += 1            continue        filtered_yjzq.append(e)    # Filter bidding: remove if URL in 中标    filtered_bidding = []    removed_from_bidding = 0    for e in bidding:        url = e.get("url", "")        if url and url in winning_urls:            removed_from_bidding += 1            continue        filtered_bidding.append(e)    # Phase 2: Title-based cross-category dedup    # Check intent against higher stages    final_intent = []    for e in filtered_intent:        dup = False        for pool in (winning, filtered_bidding, filtered_yjzq):            for w in pool:                if title_similarity(e["title"], w["title"]) > 0.75:                    removed_from_intent += 1                    dup = True                    break            if dup:                break        if not dup:            final_intent.append(e)    # Check 意见征询 against higher stages    final_yjzq = []    for e in filtered_yjzq:        dup = False        for pool in (winning, filtered_bidding):            for w in pool:                if title_similarity(e["title"], w["title"]) > 0.75:                    removed_from_yjzq += 1                    dup = True                    break            if dup:                break        if not dup:            final_yjzq.append(e)    # Check bidding against 中标    final_bidding = []    for e in filtered_bidding:        dup = False        for w in winning:            if title_similarity(e["title"], w["title"]) > 0.75:                removed_from_bidding += 1                dup = True                break        if not dup:            # Also check against 意向 and 意见征询            for i_e in final_intent:                if title_similarity(e["title"], i_e["title"]) > 0.8:                    removed_from_bidding += 1                    dup = True                    break        if not dup:            final_bidding.append(e)    total_removed = removed_from_intent + removed_from_yjzq + removed_from_bidding    if total_removed > 0:        print(            f"[DEDUP] 跨分类去重: 意向 -{removed_from_intent}, 意见征询 -{removed_from_yjzq}, 招标 -{removed_from_bidding}",            file=sys.stderr,        )    return final_intent, final_yjzq, final_bidding, winning# ── 报告生成 ──────────────────────────────────────────────def filter_taizhou_police_entries(entries: List[dict]) -> List[dict]:    """从条目列表中筛选台州公安系统相关条目"""    return [e for e in entries if is_taizhou_police(e.get("unit", ""))]def generate_section(emoji: str, title: str, entries: list) -> str:    if not entries:        return f"{emoji} {title}\n\n  暂无数据\n"    lines = [f"{emoji} {title}（共 {len(entries)} 条）"]    for item in entries:        t = item.get("title", "")        url = item.get("url", "")        unit = item.get("unit", "")        budget = item.get("budget", "")        wu = item.get("winning_unit", "")        wa = item.get("winning_amount", "")        # 项目名 + 链接        if url:            lines.append(f"  • [{t}]({url})")        else:            lines.append(f"  • {t}")        # 信息行        parts = []        if unit:            parts.append(f"🏢{unit}")        if budget:            parts.append(f"💰预算 {budget}")        if wu:            parts.append(f"🎯中标 {wu}")        if wa:            parts.append(f"💵中标价 {wa}")        if parts:            lines.append(f"    {' | '.join(parts)}")    return "\n".join(lines)# ── 主入口 ────────────────────────────────────────────────def main():    args = sys.argv[1:]    feed_path = None    if "--feed-json" in args:        i = args.index("--feed-json")        feed_path = args[i + 1]        args = args[:i] + args[i + 2:]    target_date = datetime.now()    if args:        target_date = datetime.strptime(args[0], "%Y-%m-%d")    else:        target_date -= timedelta(days=1)    date_str = target_date.strftime("%Y-%m-%d")    print(f"[INFO] 聚合 {date_str}", file=sys.stderr)    keywords = load_keywords()    zjgov_f = find_latest_data_file("zjgov_data", date_str)    tzgg_f = find_latest_data_file("tzgg_data", date_str)    lecaiyun_f = find_latest_data_file("lecaiyun_data", date_str)    tzygcg_f = find_latest_data_file("tzygcg_data", date_str)    print(f"[INFO] zjgov={zjgov_f} tzgg={tzgg_f} lecaiyun={lecaiyun_f} tzygcg={tzygcg_f}", file=sys.stderr)    zjgov = load_zjgov(zjgov_f)    tzgg = load_tzgg(tzgg_f)    lecaiyun = load_lecaiyun(lecaiyun_f, keywords)    tzygcg = load_tzygcg(tzygcg_f)    intent_raw = zjgov["意向"] + lecaiyun["意向"]    yjzq_raw = zjgov["意见征询"] + lecaiyun["意见征询"] + tzygcg["意见征询"]    bidding_raw = zjgov["招标"] + tzgg["招标"] + lecaiyun["招标"] + tzygcg["招标"]    winning_raw = zjgov["中标"] + tzgg["中标"] + lecaiyun["中标"] + tzygcg["中标"]    # 跨分类URL去重：同一URL出现在多个分类 → 只保留最高阶段（中标 > 招标 > 意见征询 > 意向）    intent_raw, yjzq_raw, bidding_raw, winning_raw = cross_category_dedup(intent_raw, yjzq_raw, bidding_raw, winning_raw)    # 跨数据源标题去重    intent = deduplicate_entries(intent_raw)    yjzq = deduplicate_entries(yjzq_raw)    bidding = deduplicate_entries(bidding_raw)    winning = deduplicate_entries(winning_raw)    total = len(intent) + len(yjzq) + len(bidding) + len(winning)    # ── 机器可读信息流（桌面工作台"行业情报"页按四类分组显示用）──    if feed_path:        all_for_police = intent + yjzq + bidding + winning        pol_ids = {id(e) for e in filter_taizhou_police_entries(all_for_police)}        def feed_items(entries, 类型):            return [                {                    "类型": 类型,                    "项目名称": e.get("title", ""),                    "采购单位": e.get("unit", ""),                    "预算": e.get("budget", ""),                    "中标单位": e.get("winning_unit", ""),                    "中标金额": e.get("winning_amount", ""),                    "链接": e.get("url", ""),                    "平台": e.get("source", ""),                    "台州公安": id(e) in pol_ids,                }                for e in entries            ]        feed = (            feed_items(intent, "采购意向")            + feed_items(yjzq, "意见征询")            + feed_items(bidding, "采购公告")            + feed_items(winning, "采购结果公告")        )        Path(feed_path).write_text(            json.dumps({"日期": date_str, "项目": feed}, ensure_ascii=False, indent=2), encoding="utf-8"        )        print(f"[INFO] 信息流已写 {feed_path}（{len(feed)} 条）", file=sys.stderr)    if total == 0:        print(f"📋 招投标每日汇总（{date_str}）\n\n今日无新增相关信息")        return    sep = "\n===MSG_SEPARATOR===\n"    sections = [generate_section("📌", f"采购意向信息（{date_str}）", intent)]    # 意见征询 - 单独推送（有数据时）    if yjzq:        sections.append(generate_section("📋", f"意见征询信息（{date_str}）", yjzq))    sections.append(generate_section("📢", f"招标信息（{date_str}）", bidding))    sections.append(generate_section("🏆", f"中标信息（{date_str}）", winning))    # ── 台州公安系统采购专项 ──    all_entries = intent + yjzq + bidding + winning    tz_police_entries = filter_taizhou_police_entries(all_entries)    if tz_police_entries:        sections.append(generate_section("🚨", f"台州公安系统采购（{date_str}）", tz_police_entries))    print(sep.join(sections))if __name__ == "__main__":    main()